// Reply to + resolve the 7 open CodeRabbit threads on PR #529.
// Run AFTER the fix commit is pushed (so commit refs are valid).
// Usage: COMMIT=<sha> node resolve-threads.mjs
import { execFileSync } from 'node:child_process';

const COMMIT = process.env.COMMIT || 'the follow-up commit';

function gh(args) {
  return execFileSync('gh', args, {
    env: { ...process.env, GITHUB_TOKEN: undefined },
    encoding: 'utf8',
    maxBuffer: 10 * 1024 * 1024,
  });
}

// thread id -> reply body
const THREADS = {
  // FIXED
  PRRT_kwDOQ6DXvM6K8yC_: `Fixed in \`${COMMIT}\`: switched the outer gate to nullish presence checks (\`!= null\`) so present-but-empty-string signature fields are treated as present and fail closed; only all-omitted records take the legacy path.`,
  PRRT_kwDOQ6DXvM6K8yC6: `Done in \`${COMMIT}\`: added an all-empty-string (\`'', '', ''\`) regression case asserting it throws \`incomplete signature data\` and never reaches verify/derive.`,
  'PRRT_kwDOQ6DXvM6K8yC-': `Fixed in \`${COMMIT}\`: test D now mocks \`addToIpfs\` success + \`createAndPublishIpnsRecord\` rejection so it exercises the real publish-failure path (still asserts the key buffer is zeroed).`,
  PRRT_kwDOQ6DXvM6K8Z__: `Fixed in \`${COMMIT}\`: the web resolve catch now checks \`error.status ?? error.response?.status\` (axios shape), matching sdk-core. Tests updated to mock \`error.response = { status: 404 }\`, plus a fallback \`error.status\` case and an empty-string fail-closed case.`,
  PRRT_kwDOQ6DXvM6K8aAR: `Fixed in \`${COMMIT}\`: added a \`zeroizing_32_from_slice\` helper (preallocate \`Zeroizing<[u8;32]>\`, length-check, then \`copy_from_slice\`) and applied it to the file/folder/IPNS key sites in \`operations.rs\` and \`platform/windows/operations.rs\` — no plain \`[u8;32]\` temporary is materialized before the zeroizing wrapper.`,
  // DEFERRED (todos)
  PRRT_kwDOQ6DXvM6K8Z_y: `Deferred (todo \`2026-06-20-ipns-publish-validate-embedded-sequence-without-cas\`): the proposed baseline-from-DB fix forces \`embedded === DB+1\` on non-CAS publish paths (desktop \`vault.rs\` and per-file publishes use \`expected_sequence_number: None\`), risking a new regression for a niche tamper case. Needs SDK-E2E validation across those paths first; out of HARD-02's immediate scope.`,
  PRRT_kwDOQ6DXvM6K8aAP: `Partially addressed: the partial-fields downgrade is fixed in \`a9d8467a0\` (\`Ok(None)\` only when all three fields absent; partial → \`Ok(Some(false))\`). The CBOR cid/sequence-binding part is a heavier lift (decode the signed CBOR and compare to \`resp.cid\`/\`resp.sequence_number\`) and is captured in todo \`2026-06-20-ipns-resolve-verify-coverage-and-web-sdk-dedup\`, to land with the resolve-verify chokepoint consolidation.`,
};

function reply(threadId, body) {
  gh([
    'api',
    'graphql',
    '-f',
    `query=mutation { addPullRequestReviewThreadReply(input: {pullRequestReviewThreadId: "${threadId}", body: ${JSON.stringify(body)}}) { comment { id } } }`,
  ]);
}
function resolve(threadId) {
  gh([
    'api',
    'graphql',
    '-f',
    `query=mutation { resolveReviewThread(input: {threadId: "${threadId}"}) { thread { isResolved } } }`,
  ]);
}

for (const [id, body] of Object.entries(THREADS)) {
  try {
    reply(id, body);
    resolve(id);
    console.log('OK   ', id);
  } catch (e) {
    console.log('FAIL ', id, String(e).slice(0, 200));
  }
}
console.log('done');

